class ATM {
    private long[] count;
    private int[] denom;

    public ATM() {
        count = new long[5];
        denom = new int[]{20, 50, 100, 200, 500};
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < 5; i++) {
            count[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        int[] used = new int[5];
        long remaining = amount;
        for (int i = 4; i >= 0; i--) {
            used[i] = (int) Math.min(count[i], remaining / denom[i]);
            remaining -= (long) used[i] * denom[i];
        }
        if (remaining > 0) return new int[]{-1};
        for (int i = 0; i < 5; i++) {
            count[i] -= used[i];
        }
        return used;
    }
}

class ATM {
    private long[] count;
    private int[] denom;

    public ATM() {
        count = new long[5];
        denom = new int[]{20, 50, 100, 200, 500};
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < 5; i++) {
            count[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        long[] temp = new long[5];
        for (int i = 0; i < 5; i++) temp[i] = count[i];
        int[] result = new int[5];
        long remaining = amount;
        for (int i = 4; i >= 0; i--) {
            long take = Math.min(temp[i], remaining / denom[i]);
            result[i] = (int) take;
            remaining -= take * denom[i];
            temp[i] -= take;
        }
        if (remaining != 0) return new int[]{-1};
        for (int i = 0; i < 5; i++) count[i] = temp[i];
        return result;
    }
}
